from pages import L
from pages5 import mk
from pages7 import SEND
from pages8 import BEFORE
TT=[('TikTok Support','https://support.tiktok.com/en','TikTok help centre with account and safety articles.'),('Feedback form','https://www.tiktok.com/feedback','Report a problem to TikTok from the web if you cannot log in.'),('Community Guidelines','https://www.tiktok.com/legal/page/global/community-guidelines/en','The rules TikTok uses for bans and restrictions.')]
WA=[('WhatsApp Help Center','https://faq.whatsapp.com/','Official answers on banned numbers and reviews.'),('Contact WhatsApp','https://www.whatsapp.com/contact/','The official contact form for account questions.'),('Terms of Service','https://www.whatsapp.com/legal/terms-of-service','The terms WhatsApp applies to bans.')]
TH=[('Account Status','https://help.instagram.com/338481628002750','Threads and Instagram share Account Status in settings.'),('Accounts Center','https://accountscenter.instagram.com/','Manage the linked Instagram and Threads profiles.'),('Threads','https://www.threads.com/','The Threads website.')]
DIR={'TikTok':('tiktok-appeal-links-and-forms-directory','TikTok appeal links directory',TT),'WhatsApp':('whatsapp-banned-number-appeal-links-directory','WhatsApp appeal links directory',WA),'Threads':('threads-appeal-links-directory','Threads appeal links directory',TH)}
def notice(slug,plat,text,title,mean,answer,steps,faqs):
    d,dn,links=DIR[plat]
    return mk(slug,title,f'“{text}” notice',f'What the {plat} notice “{text}” means, what to do in the first hour, and which official link to use. Updated November 2026.',
     f'“{text}”: what this {plat} notice means','You saw this exact message. Here is what it usually means and what to do next.',answer,
     [('Screenshot','Keep the notice and date.'),('One appeal','Plain words, once.'),('No new accounts','Wait for the decision.')],
     f'<h2 id="meaning">What it usually means</h2><p>{mean}</p><h2 id="first-hour">The first hour</h2><ol>'+''.join(f'<li>{s}</li>' for s in steps)+'</ol>',
     [('ig','Official links',links)],[BEFORE,SEND],L(d,dn)+'.',faqs)
PAGES=[
notice('tiktok-your-account-was-permanently-banned-notice','TikTok','Your account was permanently banned','“Your Account Was Permanently Banned” on TikTok: What to Do (2026)','TikTok removed the account for repeated or serious Community Guidelines violations. The notice in the app usually shows an appeal option for a limited time.','<strong>“Your account was permanently banned” on TikTok still often shows an appeal option in the app.</strong> Open the notice, tap the appeal option, and explain in plain words once. Download your data request if offered. Do not open new accounts while waiting. TikTok makes the final decision.',['Screenshot the notice and the date.','Tap the appeal option in the notice, once.','Request your data if the app offers it.','Do not open a new account while waiting.'],[('Can a permanent TikTok ban be reversed?','Sometimes, if TikTok accepts the appeal. Nobody can promise an outcome.'),('There is no appeal option. What now?','Use the feedback form from the official links directory.')]),
notice('tiktok-your-account-is-temporarily-restricted-notice','TikTok','Your account is temporarily restricted','“Your Account Is Temporarily Restricted” on TikTok: What It Means (2026)','TikTok limited features such as posting, commenting, messaging or going live for a period, usually after a guideline violation. The account is still active.','<strong>A temporary restriction on TikTok limits some features; it is not a ban.</strong> Open Account status in settings to see which rule and the end date. Appeal the violation there once if you think it was a mistake. TikTok makes the final decision.',['Open Settings, then Account status.','Read which features are limited and until when.','Appeal the specific violation once if it was a mistake.','Avoid the flagged content type until it ends.'],[('Is a restriction the same as a ban?','No. Restricted accounts keep working with some features limited.'),('Will more violations make it worse?','They can. Repeated violations can lead to a ban.')]),
notice('whatsapp-this-account-is-not-allowed-to-use-whatsapp-notice','WhatsApp','This account is not allowed to use WhatsApp','“This Account Is Not Allowed to Use WhatsApp”: What to Do (2026)','WhatsApp banned the phone number for activity it says breaks its terms, such as bulk or automated messages, or using unofficial apps. A review request option usually shows in the app.','<strong>“This account is not allowed to use WhatsApp” means the number is banned, and the app usually offers a review request.</strong> Tap request a review, add a short plain explanation, and use only the official WhatsApp app. WhatsApp makes the final decision.',['Screenshot the notice.','Tap request a review in the app, once.','Remove unofficial WhatsApp apps.','Watch for the decision in the app or by SMS.'],[('Can I use a new number?','That can break the terms too. Wait for the review decision first.'),('Is this from a modified app?','Unofficial apps are a common reason. Use only the official app.')]),
notice('whatsapp-account-can-no-longer-use-whatsapp-spam-notice','WhatsApp','This account can no longer use WhatsApp due to spam','“Can No Longer Use WhatsApp Due to Spam”: What It Means (2026)','WhatsApp believes the number sent spam, often many messages to people who do not have you saved, or broadcast use that looked automated.','<strong>A WhatsApp spam ban means the number was flagged for bulk or unwanted messages.</strong> Request a review in the app and explain how you use the number. Businesses that message customers should use the official WhatsApp Business tools. WhatsApp makes the final decision.',['Screenshot the notice.','Request a review in the app, once.','Explain normal use in plain words.','For business messaging, move to official WhatsApp Business tools.'],[('Why spam if I only messaged customers?','Messaging many people who did not save your number can look like spam.'),('Does WhatsApp Business avoid this?','It helps when used within its policy, but WhatsApp still decides.')]),
notice('threads-your-profile-has-been-restricted-notice','Threads','Your profile has been restricted','“Your Profile Has Been Restricted” on Threads: What It Means (2026)','Threads limited some features, such as posting or replying, often for a period, after a rule violation. Because Threads is linked to Instagram, check Account Status for both.','<strong>A restriction on Threads limits features; it is not a suspension.</strong> Open Account Status to see which rule and how long, and request a review once if it was a mistake. Check your Instagram account too, since the two are linked. Meta makes the final decision.',['Open Account Status in Threads or Instagram settings.','Read which features are limited.','Request a review once if it was a mistake.','Check the linked Instagram account.'],[('Does a Threads restriction affect Instagram?','Not always, but they share an account, so check both.'),('Restricted vs suspended?','Restricted limits features. Suspended blocks the profile.')]),
]
